#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;long long K,X,Y;cin>>n>>m>>K>>X>>Y;vector<long long>a(n),b(m);for(auto&v:a)cin>>v;for(auto&v:b)cin>>v;sort(a.begin(),a.end());sort(b.begin(),b.end());vector<long long>pa(n+1),pb(m+1),pc(m+1);for(int i=0;i<n;i++)pa[i+1]=pa[i]+a[i];for(int i=0;i<m;i++){pb[i+1]=pb[i]+b[i];pc[i+1]=pc[i]+(b[i]+K-1)/K;}long long ans=0,budget=X+K*Y;for(int d=0;d<=m&&pc[d]<=Y;d++){long long rem=budget-pb[d];if(rem<0)continue;int e=upper_bound(pa.begin(),pa.end(),rem)-pa.begin()-1;ans=max(ans,(long long)d+e);}cout<<ans<<'\n';}
